{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Integrative, whole-person care and practical plans for real life. Discovery, a focused agenda, and gentle follow-up." />
  <link rel="stylesheet" href="assets/css/styles.css" />
</head>
<body class="earthy">
  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <a href="/services.html">Programs</a>
        <a href="/conditions.html">Concerns</a>
        <a href="/approach.html">Philosophy</a>
        <a href="/pricing.html">Plans</a>
        <a href="/about.html">Team</a>
        <a href="/book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="/contact.html" class="muted">Connect</a>
      </nav>
      <button class="try-btn" id="open-exercise">Try the 5‑minute practice</button>
    </div>
  </header>

  <main>
    <!-- Hero -->
    <section class="hero" id="hero">
      <div class="wrap hero-grid">
        <div class="hero-content">
          <h1>Whole-life alignment, in a plan you can live with</h1>
          <p class="lead">An intensive, integrative consultation to map your body, mind, rhythms, and priorities into a clear agenda for change — without medical promises, only practical guidance.</p>
          <div class="hero-actions">
            <a href="{{PRIMARY_CTA_URL}}" class="primary">Begin your intake</a>
            <button id="open-inventory" class="secondary">Whole-person inventory</button>
          </div>
          <ul class="meta">
            <li>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
            <li>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
            <li>Serving: {{CITY}}, {{STATE}}</li>
          </ul>
        </div>
        <div class="hero-art">
          <img src="assets/img/pattern.svg" alt="decorative pattern" class="pattern" aria-hidden="true" />
        </div>
      </div>
    </section>

    <!-- Social Proof -->
    <section class="social" id="social-proof">
      <div class="wrap">
        <h2>Voices from the work</h2>
        <div class="testimonials">
          <blockquote>
            "A single intensive that finally made sense of months of confusing advice. The agenda was simple and doable."
            <cite>— L., client</cite>
          </blockquote>
          <blockquote>
            "I left with practical steps and a follow-up rhythm that actually fit my schedule. No fluff." <cite>— M., client</cite>
          </blockquote>
        </div>
        <div class="trust">
          <span>Clinically informed • Evidence-aware • Person-centered</span>
        </div>
      </div>
    </section>

    <!-- Benefits (reordered to provide unique flow) -->
    <section class="benefits" id="benefits">
      <div class="wrap">
        <h2>What this intensive delivers</h2>
        <div class="grid">
          <div class="card">
            <h3>Focused intake</h3>
            <p>One deep session collecting context: sleep, stressors, relationships, digestion, energy, and goals.</p>
          </div>
          <div class="card">
            <h3>Practical agenda</h3>
            <p>A short, prioritized plan you can start in the first week — measurable and reviewable.</p>
          </div>
          <div class="card">
            <h3>Follow-up cadence</h3>
            <p>Gentle checkpoints matched to your needs: timing, metrics, and who to loop in.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Process -->
    <section class="process" id="process">
      <div class="wrap">
        <h2>How it works</h2>
        <ol>
          <li><strong>Preparation:</strong> A short form primes the visit — what matters most, and key history.</li>
          <li><strong>Intensive session:</strong> A structured review of domains to build an integrative agenda.</li>
          <li><strong>Focused interventions:</strong> Small, evidence-minded steps (sleep, movement, nutrition, mindfulness, coordination with other care).</li>
          <li><strong>Follow-up:</strong> A tailored cadence (text, call, or brief video) and a shared agenda to track progress.</li>
        </ol>
      </div>
    </section>

    <!-- FAQ (unique order placement) -->
    <section class="faq" id="faq">
      <div class="wrap">
        <h2>Questions people ask</h2>
        <details>
          <summary>Do you offer diagnosis or medical treatment?</summary>
          <p>This program is educational and integrative. We do not replace emergency or specialist care. We collaborate with your clinicians when needed.</p>
        </details>
        <details>
          <summary>How long until I see change?</summary>
          <p>Changes vary. The agenda emphasizes early, trackable steps within 2–6 weeks with iterative review cycles.</p>
        </details>
        <details>
          <summary>Is this covered by insurance?</summary>
          <p>Coverage varies. We provide documentation that may be submitted to insurers; check your plan.</p>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" id="cta">
      <div class="wrap">
        <h2>Ready to translate your life into an actionable plan?</h2>
        <p class="sub">Start with a single intensive session and a clear follow-up rhythm tailored to you.</p>
        <div class="actions">
          <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button id="open-inventory-2" class="secondary">Try the whole-person inventory</button>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <small>&copy; <span id="year"></span> {{BUSINESS_NAME}} — Integrative consultation services. Not a substitute for medical care.</small>
      <nav class="foot-nav">
        <a href="/about.html">About</a>
        <a href="/contact.html">Contact</a>
        <a href="/privacy.html">Privacy</a>
      </nav>
    </div>
  </footer>

  <!-- Inventory Modal -->
  <div id="inventory-modal" class="modal" aria-hidden="true">
    <div class="modal-content">
      <button class="close" id="close-inventory" aria-label="Close">×</button>
      <h3>Whole-person inventory</h3>
      <p>Select the areas you want prioritized. We'll produce a consultation agenda and a suggested follow-up cadence.</p>
      <form id="inventory-form">
        <div class="check-grid">
          <label><input type="checkbox" name="domain" value="Sleep" /> Sleep and rest</label>
          <label><input type="checkbox" name="domain" value="Nutrition" /> Nutrition and digestion</label>
          <label><input type="checkbox" name="domain" value="Movement" /> Movement and strength</label>
          <label><input type="checkbox" name="domain" value="Stress" /> Stress and coping</label>
          <label><input type="checkbox" name="domain" value="Energy" /> Energy and stamina</label>
          <label><input type="checkbox" name="domain" value="Mood" /> Mood and emotional regulation</label>
          <label><input type="checkbox" name="domain" value="Focus" /> Attention and cognitive clarity</label>
          <label><input type="checkbox" name="domain" value="Relationships" /> Relationships and support</label>
        </div>
        <label class="short">What is your main goal? <input type="text" name="goal" placeholder="e.g., sleep 7 hours, reduce midday crashes" /></label>
        <div class="modal-actions">
          <button type="submit" class="primary">Generate Agenda</button>
          <button type="button" class="secondary" id="close-inventory-2">Cancel</button>
        </div>
      </form>
      <div id="inventory-result" class="inventory-result" aria-live="polite"></div>
    </div>
  </div>

  <!-- Guided Exercise Modal -->
  <div id="exercise-modal" class="modal" aria-hidden="true">
    <div class="modal-content exercise">
      <button class="close" id="close-exercise" aria-label="Close">×</button>
      <h3>5‑Minute Guided Practice</h3>
      <p id="exercise-instruction">Choose a focus to begin.</p>
      <div class="exercise-controls">
        <select id="exercise-type">
          <option value="breath">Breathing</option>
          <option value="journaling">Journaling prompt</option>
          <option value="intention">Set an intention</option>
        </select>
        <button id="start-exercise" class="primary">Start</button>
      </div>
      <div id="exercise-stage" class="exercise-stage" aria-live="polite"></div>
      <div class="modal-actions">
        <button id="skip-exercise" class="secondary">Close</button>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
